// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Connection state of GitHub and Jira
	// (GET /api/accounts)
	GetAccounts(w http.ResponseWriter, r *http.Request)
	// Remove the stored tokens of a provider
	// (DELETE /api/accounts/{provider})
	DisconnectAccount(w http.ResponseWriter, r *http.Request, provider Provider)
	// Check a connection with the provider now
	// (POST /api/accounts/{provider}/check)
	CheckAccount(w http.ResponseWriter, r *http.Request, provider Provider)
	// The activity log, newest first
	// (GET /api/activity)
	GetActivity(w http.ResponseWriter, r *http.Request, params GetActivityParams)
	// Validate and store a GitHub personal access token
	// (PUT /api/github/pat)
	PutGithubPat(w http.ResponseWriter, r *http.Request)
	// Finish an OAuth authorization with the code and state from the provider redirect
	// (POST /api/oauth/complete)
	CompleteOAuth(w http.ResponseWriter, r *http.Request)
	// Merge a pull request and move its tickets
	// (POST /api/prs/{id}/merge)
	MergePr(w http.ResponseWriter, r *http.Request, id PrId, params MergePrParams)
	// Set the manual ticket links and the hidden keys of a pull request
	// (PUT /api/prs/{id}/tickets)
	PutPrTickets(w http.ResponseWriter, r *http.Request, id PrId)
	// Every repository the dashboard has seen, with its merge settings
	// (GET /api/repos)
	ListRepos(w http.ResponseWriter, r *http.Request)
	// Merge settings of one repository
	// (GET /api/repos/{id})
	GetRepo(w http.ResponseWriter, r *http.Request, id RepoId)
	// Set the default method and replace the branch rules of a repository
	// (PUT /api/repos/{id})
	PutRepo(w http.ResponseWriter, r *http.Request, id RepoId)
	// Failed transitions waiting for a retry
	// (GET /api/retries)
	ListRetries(w http.ResponseWriter, r *http.Request)
	// Forget a failed transition
	// (DELETE /api/retries/{id})
	DismissRetry(w http.ResponseWriter, r *http.Request, id RetryId)
	// Try a failed transition again
	// (POST /api/retries/{id})
	RetryTransition(w http.ResponseWriter, r *http.Request, id RetryId)
	// Session info and CSRF token
	// (GET /api/session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// Exchange a one-time launch token for a session cookie
	// (POST /api/session)
	CreateSession(w http.ResponseWriter, r *http.Request)
	// Sign out every browser, including this one
	// (POST /api/sessions/revoke-all)
	RevokeAllSessions(w http.ResponseWriter, r *http.Request)
	// Global settings
	// (GET /api/settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// Replace the global settings
	// (PUT /api/settings)
	PutSettings(w http.ResponseWriter, r *http.Request)
	// Which OAuth apps are configured, and the callback URLs to register
	// (GET /api/setup)
	GetSetup(w http.ResponseWriter, r *http.Request)
	// Store the OAuth app client credentials of a provider in the secrets store
	// (PUT /api/setup/{provider})
	PutSetupClient(w http.ResponseWriter, r *http.Request, provider Provider)
	// The latest dashboard snapshot
	// (GET /api/snapshot)
	GetSnapshot(w http.ResponseWriter, r *http.Request, params GetSnapshotParams)
	// Start a refresh now
	// (POST /api/sync)
	SyncNow(w http.ResponseWriter, r *http.Request)
	// Jira tickets assigned to the user, for the ticket picker
	// (GET /api/tickets/assigned)
	GetAssignedTickets(w http.ResponseWriter, r *http.Request)
	// Transitions available for a ticket, with the fields they require
	// (GET /api/tickets/{key}/transitions)
	GetTransitions(w http.ResponseWriter, r *http.Request, key TicketKey)
}

